files.content:
:root,
[data-ui-theme="ledger"] {
  --ui-background: #f4f1ec;
  --ui-content-width: 1200px;
  --ui-content-wide: 1440px;
  --ui-gutter: clamp(20px, 4vw, 50px);
  --ui-radius-dialog: 8px;
  --ui-overlay: rgb(30 30 30 / 28%);
  --ui-layer-overlay: 100;
  --ui-layer-dialog: 101;
  --ui-layer-floating: 110;
  --ui-success-foreground: #205b39;
  --ui-warning-foreground: #76500d;
  --ui-info-foreground: #2448a5;
  --ui-foreground: #1e1e1e;
  --ui-primary: #1e1e1e;
  --ui-primary-foreground: #f4f1ec;
  --ui-primary-hover: #000;
  --ui-muted: #ebe7e0;
  --ui-muted-foreground: #62605b;
  --ui-popover: #faf8f4;
  --ui-border: #d6d1c9;
  --ui-border-strong: #aaa6a0;
  --ui-input: #85817b;
  --ui-destructive: #8b302e;
  --ui-ring: #1e1e1e;
  --ui-radius: 6px;
  --ui-control-height: 34px;
  --ui-font-interface: "Inter", "Segoe UI", sans-serif;
  --ui-font-editorial: "Cormorant Garamond", Georgia, serif;
}
[data-ui-theme="studio"] {
  --ui-radius-dialog: 12px;
  --ui-background: #f7f9fc;
  --ui-foreground: #172235;
  --ui-primary: #2448a5;
  --ui-primary-foreground: #fff;
  --ui-primary-hover: #19367f;
  --ui-muted: #e9eef7;
  --ui-muted-foreground: #4b596d;
  --ui-popover: #fff;
  --ui-border: #cbd3df;
  --ui-border-strong: #8b97a8;
  --ui-input: #748197;
  --ui-destructive: #a12b35;
  --ui-ring: #2448a5;
  --ui-radius: 10px;
  --ui-font-interface: "Inter", "Segoe UI", sans-serif;
  --ui-font-editorial: "Inter", "Segoe UI", sans-serif;
}

[data-ui-theme="wedding-admin"] {
  --ui-background: #fff;
  --ui-surface: #fff;
  --ui-canvas-subtle: #f6f7f8;
  --ui-foreground: #0a0a0a;
  --ui-primary: #000;
  --ui-primary-foreground: #fff;
  --ui-primary-hover: #222;
  --ui-muted: #f2f2f2;
  --ui-muted-foreground: #666;
  --ui-popover: #fff;
  --ui-border: #e5e5e5;
  --ui-border-strong: #8a8a8a;
  --ui-input: #737373;
  --ui-destructive: #c22b10;
  --ui-ring: #0a0a0a;
  --ui-success-foreground: #176b2c;
  --ui-warning-foreground: #765800;
  --ui-info-foreground: #2448a5;
  --ui-status-success: #10c22b;
  --ui-status-warning: #d9a900;
  --ui-radius: 10px;
  --ui-radius-card: 14px;
  --ui-radius-dialog: 14px;
  --ui-control-height: 32px;
  --ui-font-interface: "Geist", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --ui-font-editorial: var(--ui-font-interface);
  --ui-font-mono: "Geist Mono", "IBM Plex Mono", "SFMono-Regular", Menlo, monospace;
  --ui-page-title-size: 48px;
  --ui-page-title-weight: 600;
  --ui-page-title-leading: 1;
  --ui-page-title-tracking: -2.4px;
  --ui-page-header-padding: 0 0 32px;
  --ui-page-header-padding-mobile: 0 0 24px;
  --ui-section-title-size: 18px;
  --ui-section-title-weight: 600;
  --ui-section-border: 0;
  --ui-section-header-padding: 0 0 16px;
  --ui-sidebar-width: 260px;
  --ui-sidebar-collapsed-width: 84px;
  --ui-drawer-width: min(520px, 92vw);
  --ui-card-padding: 16px;
  --ui-stack-sm: 8px;
  --ui-stack-md: 16px;
  --ui-stack-lg: 32px;
}
@media (max-width: 560px) {
  [data-ui-theme="wedding-admin"] {
    --ui-page-title-size: clamp(30px, 8vw, 40px);
    --ui-page-title-tracking: -0.45px;
    --ui-control-height: 44px;
  }
}

@media (pointer: coarse), (max-width: 540px) {
  :root,
  [data-ui-theme] {
    --ui-control-height: 44px;
  }
}
